const KEY_ORDER = Object.keys(EN).filter((k) => k !== 'appName');
KEY_ORDER.unshift('appName');

function fromArray(arr) {
  const o = { appName: 'DiscordBabel' };
  
  
  const keys = KEY_ORDER.filter((k) => k !== 'appName');
  keys.forEach((k, i) => {
    if (arr[i] !== undefined) o[k] = arr[i];
  });
  return o;
}

for (const [loc, arr] of Object.entries(MORE)) {
  PACKS[loc] = fromArray(arr);
}

